Here is an example code in C for 11-point linear interpolation in ADC calibration:
```c
#include <stdint.h>

// Define the ADC calibration points
#define CAL_POINTS 11

// Define the ADC calibration points array (in volts)
uint16_t cal_points[CAL_POINTS] = {
  0x0000,  // 0V
  0x0f3b,  // 0.5V
  0x1e66,  // 1V
  0x2b89,  // 1.5V
  0x396c,  // 2V
  0x3d9f,  // 2.5V
  0x47a2,  // 3V
  0x51d5,  // 3.5V
  0x5c78,  // 4V
  0x6fbb,  // 4.5V
  0x7fde  // 5V
};

// Define the ADC counts for each calibration point (in counts)
uint16_t adc_counts[CAL_POINTS] = {
  0x0000,  // 0V
  0x1a2e,  // 0.5V
  0x3a5c,  // 1V
  0x5a80,  // 1.5V
  0x7a9c,  // 2V
  0x9ac6,  // 2.5V
  0xbb70,  // 3V
  0xd1b4,  // 3.5V
  0xf1f8,  // 4V
  0x11fbc,  // 4.5V
  0x13fe6  // 5V
};

// Define the linear interpolation function
uint16_t linear_interpolation(uint16_t input_voltage) {
  uint16_t result = 0;

  // Find the two nearest calibration points
  uint16_t idx1 = 0;
  uint16_t idx2 = 0;
  for (uint16_t i = 0; i < CAL_POINTS - 1; i++) {
    if (input_voltage <= cal_points[i + 1]) {
      idx2 = i + 1;
    }
    if (input_voltage <= cal_points[i]) {
      idx1 = i;
    }
  }

  // Perform linear interpolation
  uint16_t voltage_diff = cal_points[idx2] - cal_points[idx1];
  uint16_t count_diff = adc_counts[idx2] - adc_counts[idx1];
  uint16_t fraction = (input_voltage - cal_points[idx1]) * 100; // Multiply by 100 to convert to 10-bit fraction
  result = adc_counts[idx1] + (fraction * count_diff) / 100;

  return result;
}

int main() {
  uint16_t input_voltage = 2.3; // Example input voltage
  uint16_t output_count = linear_interpolation(input_voltage);
  printf("ADC count for %fV: 0x%x\n", input_voltage, output_count);
  return 0;
}
```
This code defines the ADC calibration points in volts and counts, and implements a linear interpolation function to calculate the ADC count for a given input voltage. The `linear_interpolation` function finds the two nearest calibration points, performs linear interpolation, and returns the calculated ADC count.

Note that this code assumes a 10-bit ADC with a 1.024V full-scale range (i.e., 0 to 1024 counts). You may need to adjust the code to match your specific ADC and calibration requirements.

