#define NUM_POINTS 11

// Define the ADC voltage range
#define ADC_VOLTAGE_RANGE 1.0

// Define the interpolation function
double interpolateVoltage(double voltage) {
  // Calculate the interpolation factor
  double factor = (voltage - ADC_VOLTAGE_RANGE[0]) / (ADC_VOLTAGE_RANGE[1] - ADC_VOLTAGE_RANGE[0]);

  // Apply the interpolation formula
  double interpolatedVoltage = ADC_VOLTAGE_RANGE[0] + factor * (ADC_VOLTAGE_RANGE[1] - ADC_VOLTAGE_RANGE[0]);

  // Map the interpolated voltage to the range [0, 1]
  interpolatedVoltage = interpolatedVoltage / ADC_VOLTAGE_RANGE[1];

  return interpolatedVoltage;
}

